class C
{
    T M<T>(T x, T y) => throw null;
    void M2()
    {
        var t = M((a: 1, b: "hello"), (a: default, b: null));
        t.a.ToString();
        t.b.ToString();

        var t2 = M((a: 1, b: "hello"), (a: default, z: null)); // 1
        t2.a.ToString();
        t2.b.ToString();

        var t3 = M((1, "hello"), (a: default, b: null)); // 2, 3
        t3.a.ToString(); // 4
        t3.b.ToString(); // 5
    }
}

